//! Git repositories for tests, kept as `git fast-export` streams in
//! `fixtures/` and regenerated by `fixtures/generate.sh`.

use std::io::Write;
use std::path::Path;
use std::process::{Command, Stdio};

/// `lib.c`: a flaw introduced in v1.1, refactored in v1.2, fixed in v1.3.
pub const HISTORY: &str = include_str!("../fixtures/history.fi");

/// `src/lib.c`: two untagged commits, `initial` and `fix`.
pub const SIMPLE: &str = include_str!("../fixtures/simple.fi");

fn git(dir: &Path, args: &[&str]) -> Command {
    let mut command = Command::new("git");
    command.args(args).current_dir(dir);
    command
}

/// Import `stream` into a new repository at `dir`, with `main` checked out.
pub fn import(stream: &str, dir: &Path) {
    std::fs::create_dir_all(dir).unwrap();
    let status = git(dir, &["init", "-q", "-b", "main"]).status().unwrap();
    assert!(status.success(), "git init failed");

    let mut child = git(dir, &["fast-import", "--quiet"])
        .stdin(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(stream.as_bytes())
        .unwrap();
    assert!(child.wait().unwrap().success(), "git fast-import failed");

    let status = git(dir, &["reset", "-q", "--hard"]).status().unwrap();
    assert!(status.success(), "git reset failed");
}
